fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        // Empty array stays empty
        return Vec::new();
    }

    // Reduce the offset modulo n so we only rotate as much as needed
    let k = offset % n;

    // Allocate the result with the correct size
    let mut b = Vec::with_capacity(n);

    // For each target index i, pick from (i + k) % n in the original
    for i in 0..n {
        b.push(a[(i + k) % n]);
    }

    b
}

